// Builds the generated parts of the skill from src/: the page with its engine, parser, app and fonts inside
// (assets/process-simulation.html, which scripts/build.mjs fills with the recipes), and the engine and parser as an ES module,
// twice — for scripts/build.mjs (scripts/engine.mjs) and for the mod (hooks/process-simulation/sim-core.js). The fonts come
// from @fontsource (OFL), so the page opens offline. Run: npm run assets. Never edit the generated files by hand.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const src = resolve(here, '../src')
const repo = resolve(here, '../../..') // the dna repository
const skill = join(repo, 'skills/process-simulation')
const read = (f) => readFileSync(join(src, f), 'utf8')
const release = JSON.parse(readFileSync(join(repo, '.claude-plugin/plugin.json'), 'utf8')).version

// the fonts, inside the page
const font = (pkg, file) => readFileSync(join(repo, 'node_modules/@fontsource', pkg, 'files', file)).toString('base64')
const face = (family, weight, data) => `@font-face{font-family:'${family}';font-style:normal;font-weight:${weight};font-display:swap;src:url(data:font/woff2;base64,${data}) format('woff2')}`
const fonts = [
  ...[600, 700].map((w) => face('Bricolage Grotesque', w, font('bricolage-grotesque', `bricolage-grotesque-latin-${w}-normal.woff2`))),
  ...[400, 500, 600].map((w) => face('IBM Plex Sans', w, font('ibm-plex-sans', `ibm-plex-sans-latin-${w}-normal.woff2`))),
  ...[400, 500].map((w) => face('IBM Plex Mono', w, font('ibm-plex-mono', `ibm-plex-mono-latin-${w}-normal.woff2`))),
].join('\n')

// the page: everything but the recipes (/*EXAMPLES*/) and the screen's first language (/*START_UI*/)
const parts = { GENERATOR: `process-simulation (dna ${release})`, RELEASE: `process-simulation ${release}`, FONTS: fonts, ENGINE: read('engine.js'), PARSER: read('parser.js'), APP: read('app.js') }
let page = read('page.html')
for (const [k, v] of Object.entries(parts)) {
  if (!page.includes(`/*${k}*/`)) throw new Error(`page.html has no /*${k}*/`)
  page = page.replace(`/*${k}*/`, () => v)
}
if (/<(script|link|img)\b[^>]*\b(src|href)=["']?https?:/i.test(page)) throw new Error('the page would load something from the internet')
writeFileSync(join(skill, 'assets/process-simulation.html'), page)

// the engine and parser as an ES module (the worker part stays in the page)
const core = (who) => `// GENERATED by dev/process-simulation/tools/assets.mjs from src/engine.js, src/parser.js and src/attest.js, for ${who}. Do not edit.\n` +
  read('engine.js').split('/* Worker side')[0] + '\n' + read('parser.js') + '\n' + read('attest.js') + '\nexport { BO, SIMLANG, ATTEST }\n'
writeFileSync(join(skill, 'scripts/engine.mjs'), core('scripts/build.mjs'))
writeFileSync(join(repo, 'hooks/process-simulation/sim-core.js'), core('the mod'))
console.log(`✓ assets of process-simulation ${release}: process-simulation.html ${(page.length / 1024).toFixed(0)} KB, engine.mjs, hooks/process-simulation/sim-core.js`)
